"use client";

import { useEffect, useState } from "react";
import { motion } from "motion/react";

export function TypewriterTailwind({ words = ["interfaces", "landing pages", "dashboards"], prefix = "Build" }) {
  const [i, setI] = useState(0);
  const [text, setText] = useState("");
  const [del, setDel] = useState(false);
  const word = words[i % words.length];
  useEffect(() => {
    let t: ReturnType<typeof setTimeout> | undefined;
    if (!del && text === word) t = setTimeout(() => setDel(true), 1400);
    else if (del && text === "") { setDel(false); setI((n) => n + 1); }
    else t = setTimeout(() => setText(word.slice(0, text.length + (del ? -1 : 1))), del ? 35 : 70);
    return () => clearTimeout(t);
  }, [text, del, word]);
  return (
    <span className="text-3xl font-semibold tracking-tight text-zinc-100">
      {prefix} <span className="text-sky-400">{text}</span>
      <motion.span
        aria-hidden
        className="ml-0.5 inline-block h-[1em] w-[0.08em] bg-sky-400 align-middle"
        animate={{ opacity: [1, 0] }}
        transition={{ duration: 0.6, repeat: Infinity, repeatType: "reverse" }}
      />
    </span>
  );
}
